#!/usr/bin/env python3
"""Compare shipped generated bytes with two isolated, network-free rebuilds.

The live website is read only. Only verification/reproducibility.json is written
there. Release reports, browser records and checksum manifests are not compared:
their contents depend on verification and would introduce circular hashes.
"""
from __future__ import annotations

import hashlib
import json
import os
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
METHOD = "isolated_graph_and_site_two_builds_v13"


def read(root, path):
    return json.loads((root / path).read_text(encoding="utf-8"))


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest() if path.is_file() else None


def input_paths(root):
    names = [
        'source/atlas_v12_original.html', 'source/article_update_20261018.json',
        'source/ndse2_book.json', 'source/site_config.json',
        'source/atlas_v13_template.py', 'source/build_graph_v13.py',
        'source/build_site.py', 'source/build_ndse2_pages.py',
        'source/atlas_navigation_patch.js', 'source/author_provenance.json',
        'source/original_catalogue_provenance.json', 'source/baseline_provenance.json',
        'source/update_baseline_20261018.json', 'source/check_reproducibility.py',
        'data/graph/knowledge_graph_v12.json', 'data/graph/knowledge_graph_v12.graphml',
    ]
    names += [p.relative_to(root).as_posix() for p in sorted((root / 'data/originals').glob('*')) if p.is_file()]
    return sorted(set(names))


def output_paths(root):
    config = read(root, 'source/site_config.json')
    names = list(read(root, 'source/page_inventory.json'))
    names += [p.relative_to(root).as_posix() for p in sorted((root / 'data/catalogues').glob('*')) if p.is_file()]
    names += [
        'source/' + config.get('atlas_source', 'atlas_v13_current.html'),
        config.get('graph_json', 'data/graph/knowledge_graph_v13.json'),
        config.get('graph_graphml', 'data/graph/knowledge_graph_v13.graphml'),
        'data/graph/atlas_payload_v13.json',
        'data/updates/ndse2_source_manifest.json',
        'data/updates/ndse2_citation_occurrences.json',
        'verification/graph_update_checks.json',
        'README.md', 'DEPLOYMENT.md', 'ATTRIBUTION.md',
        'source/page_inventory.json', 'source/build_summary.json',
        'data/catalogue-data.zip',
    ]
    excluded = {
        'UPDATE_20261018.html', 'verification/report.html',
        'verification/release_summary.json', 'verification/reproducibility.json',
        'verification/structure_checks.json', 'verification/browser_checks.json',
        'verification/relationship_switch_checks.json', 'verification/visual_checks.json',
        'SHA256SUMS.txt',
    }
    return sorted(set(names) - excluded)


# Both builders use only the standard library and frozen local files. The audit
# hook also refuses Python socket creation/lookup/connect operations in each run.
RUNNER = """
from pathlib import Path
import runpy
import sys
def prohibit_network(event, args):
    if event.startswith('socket.'):
        raise RuntimeError('Network operations are disabled during reproducibility checks: ' + event)
sys.addaudithook(prohibit_network)
sys.argv = [sys.argv[1]]
sys.path.insert(0, str(Path(sys.argv[0]).parent))
runpy.run_path(sys.argv[0], run_name='__main__')
"""


def run_builds(root):
    env = os.environ.copy()
    env['PYTHONDONTWRITEBYTECODE'] = '1'
    env['PYTHONHASHSEED'] = '0'
    for name in ['build_graph_v13.py', 'build_site.py']:
        command = [sys.executable, '-c', RUNNER, str(root / 'source' / name)]
        done = subprocess.run(command, cwd=root, env=env, text=True, capture_output=True, check=False)
        if done.returncode:
            raise RuntimeError(name + ' failed: ' + (done.stderr or done.stdout)[-6000:])


def main():
    config = read(ROOT, 'source/site_config.json')
    original_inputs = {p: digest(ROOT / p) for p in input_paths(ROOT)}
    missing_inputs = [p for p, value in original_inputs.items() if value is None]
    paths = output_paths(ROOT)
    delivered = {p: digest(ROOT / p) for p in paths}
    graph_hash = digest(ROOT / 'swe_knowledge_graph.html')
    checks, input_checks, error = [], [], None
    first, second = {}, {}
    try:
        if missing_inputs:
            raise RuntimeError('Missing frozen inputs: ' + ', '.join(missing_inputs))
        with tempfile.TemporaryDirectory(prefix='knowledge-atlas-rebuild-') as temporary:
            workspace = Path(temporary) / 'site'
            shutil.copytree(ROOT, workspace, ignore=shutil.ignore_patterns('__pycache__', '*.pyc', '.git'))
            copied_inputs = {p: digest(workspace / p) for p in original_inputs}
            if copied_inputs != original_inputs:
                raise RuntimeError('Frozen input copy did not match the live input snapshot.')
            run_builds(workspace)
            first_paths = output_paths(workspace)
            first = {p: digest(workspace / p) for p in first_paths}
            run_builds(workspace)
            second_paths = output_paths(workspace)
            second = {p: digest(workspace / p) for p in second_paths}
            paths = sorted(set(paths) | set(first_paths) | set(second_paths))
            for path in paths:
                values = [delivered.get(path), first.get(path), second.get(path)]
                checks.append({
                    'path': path, 'delivered_sha256': values[0],
                    'first_rebuild_sha256': values[1], 'second_rebuild_sha256': values[2],
                    'delivered_matches_rebuild': values[0] is not None and values[0] == values[1],
                    'two_rebuilds_identical': values[1] is not None and values[1] == values[2],
                    'passed': values[0] is not None and values[0] == values[1] == values[2],
                })
            for path, before in original_inputs.items():
                after_live, after_copy = digest(ROOT / path), digest(workspace / path)
                input_checks.append({'path': path, 'sha256': before,
                                     'live_unchanged': before == after_live,
                                     'rebuild_input_unchanged': before == after_copy,
                                     'passed': before == after_live == after_copy})
    except Exception as exception:
        error = str(exception)
    failed = sum(not c['passed'] for c in checks) + sum(not c['passed'] for c in input_checks) + bool(error)
    result = {
        'as_of': config['build_date'], 'site_version': config['site_version'],
        'graph_version': config['graph_version'], 'graph_snapshot': config['graph_snapshot'],
        'method_id': METHOD, 'complete': error is None,
        'method': 'Frozen inputs; graph then static site rebuilt twice in an isolated copy; both runs compared to delivered generated bytes with SHA-256.',
        'network': 'No source refresh; Python socket operations prohibited by an audit hook.',
        'live_site_rebuilt': False, 'graph_html_sha256': graph_hash,
        'python_version': sys.version.split()[0], 'outputs_tested': len(checks),
        'passed': sum(c['passed'] for c in checks), 'failed': int(failed),
        'input_files_checked': len(input_checks), 'input_files_failed': sum(not c['passed'] for c in input_checks),
        'delivered_outputs_match_rebuild': bool(checks) and all(c['delivered_matches_rebuild'] for c in checks),
        'two_rebuilds_identical': bool(checks) and all(c['two_rebuilds_identical'] for c in checks),
        'excluded_from_byte_comparison': [
            'Current update/release report and release summary',
            'Runtime structural, browser and visual check records',
            'This reproducibility record',
            'Package checksum manifests and final release archives',
        ],
        'graph_update_checks_included': True,
        'scope': 'Checks frozen-input graph/site regeneration; does not rerun source research, manuscript extraction, browser QA or final-archive packaging.',
        'checks': checks, 'input_checks': input_checks, 'error': error,
    }
    (ROOT / 'verification/reproducibility.json').write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    print(json.dumps({k: result[k] for k in ['complete', 'outputs_tested', 'passed', 'failed', 'input_files_checked', 'delivered_outputs_match_rebuild', 'two_rebuilds_identical', 'error']}, indent=2))
    if failed:
        print(json.dumps([c for c in checks if not c['passed']], indent=2))
        return 1
    return 0


if __name__ == '__main__':
    sys.exit(main())
